import { APIError } from 'payload';
import { uploadFileData } from './uploadFileData.js';
const PRESIGNED_DOWNLOAD_URL_EXPIRES_IN_SECONDS = 300;
/**
 * Copies `from` to `to` and keeps `from`, so older versions can still read it.
 *
 * The Content API has no copy endpoint, so the bytes are downloaded and uploaded again with
 * the source Content-Type. The Content API stores no other object metadata.
 *
 * The destination check is not atomic. Payload puts a new `_objectKey` in `to`, so two
 * copies to the same key at the same time are not expected.
 */ export const getCopyFile = ({ client })=>{
    return async ({ collection, from, mimeType, req, to })=>{
        if (from === to) {
            throw new Error('Storage copy requires different source and destination keys');
        }
        const collectionId = collection.slug;
        // The Content API role can list the bucket, so a missing object returns 404, not 403.
        const destination = await fetchObject({
            client,
            collectionId,
            headers: {
                Range: 'bytes=0-0'
            },
            key: to,
            signal: req.signal
        });
        await cancelResponseBody(destination);
        if (destination.status !== 404) {
            if (destination.ok || destination.status === 416) {
                throw new APIError(`Storage destination already exists: ${to}`, 409);
            }
            throw new Error(`Failed to check storage destination: ${destination.status}`);
        }
        const source = await fetchObject({
            client,
            collectionId,
            key: from,
            signal: req.signal
        });
        if (!source.ok) {
            await cancelResponseBody(source);
            throw new Error(`Failed to read storage source: ${source.status}`);
        }
        const fileData = Buffer.from(await source.arrayBuffer());
        await uploadFileData({
            client,
            collectionId,
            fileData,
            fileKey: to,
            mimeType: source.headers.get('Content-Type') || mimeType || 'application/octet-stream'
        });
    };
};
async function fetchObject({ client, collectionId, headers, key, signal }) {
    const { data, error, response } = await client.POST('/api/v0/uploads/download/sign', {
        body: {
            collectionId,
            expiresIn: PRESIGNED_DOWNLOAD_URL_EXPIRES_IN_SECONDS,
            filename: key,
            responseHeaders: {
                cacheControl: 'private, no-store'
            }
        }
    });
    if (error) {
        throw new APIError(`Failed to get presigned download URL: ${error.message}`, response.status, {
            code: error.code
        });
    }
    if (!data) {
        throw new Error('No response while getting presigned download URL');
    }
    try {
        return await fetch(data.url, {
            headers,
            signal
        });
    } catch  {
        // Fetch errors can contain the signed URL; throw only a fixed message to avoid exposing it.
        throw new Error('Failed to fetch file from storage');
    }
}
async function cancelResponseBody(response) {
    try {
        await response.body?.cancel();
    } catch  {
    // The body is not read; cancellation is best-effort cleanup.
    }
}
